  root.classList.add('stage');
  root.innerHTML=`<div class="gl"></div><div class="glyph" title="ক্লিক করলে স্ট্রোক অ্যানিমেশন">${c.k}</div><svg class="sv" viewBox="0 0 109 109"><g class="ol"></g><g class="hn"></g><g class="dn"></g><g class="nm"></g><circle class="pen" r="2.4" cx="-9" cy="-9"></circle></svg><canvas class="cv"></canvas><div class="tip"></div>`;
